function landscape(key,title,kicker,body,href,label){return `<section class="landscape-panel" data-parallax-scene="flow"><img class="landscape-backdrop" src="assets/environment-${key}-base.svg" alt="" data-speed="40" loading="lazy"><img class="landscape-foreground" src="assets/environment-${key}-foreground.svg" alt="" data-speed="-65" loading="lazy"><div class="landscape-wash"></div><div class="landscape-copy" data-speed="-25"><span class="eyebrow">${kicker}</span><h2>${title}</h2><p>${body}</p>${href?`<a href="${href}" class="button primary">${label} ${icon('arrow')}</a>`:''}</div><span class="landscape-credit">CENÁRIO ILUSTRATIVO DO ATLAS</span></section>`}
function portraitSource(c){return c.imageSource?`<a class="source-link image-source-link" href="${c.imageSource}" target="_blank" rel="noopener noreferrer">Imagem · Avatar Wiki / Fandom ↗</a>`:''}
function characterCard(c){return `<article class="cast-card ${c.element}" id="${c.id}" data-cast-element="${c.element}" data-era="${c.era}" data-search="${c.name} ${c.skills} ${c.text}"><div class="cast-art">${c.image?pic(c.image,c.name):`<div class="cast-monogram" aria-hidden="true">${c.element==='nao'?icon('compass'):icon(c.element)}<span>${c.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span></div>`}<span class="cast-label">${GROUPS[c.element]}</span></div><div class="cast-copy"><span class="eyebrow">${ERAS[c.era]}</span><h3>${c.name}</h3><p>${c.text}</p><details><summary>Habilidades e fonte</summary><p>${c.skills}.</p>${link(c.source)}${portraitSource(c)}</details></div></article>`}
function elementRoster(key){return `<div class="cast-grid element-roster">${CAST.filter(c=>c.element===key).map(characterCard).join('')}</div><p class="editor-note">Os Avatares aparecem pelo elemento de origem e podem aprender os quatro. Nacionalidade não determina se uma pessoa dobra: Sokka pertence à Água; Suki, ao Reino da Terra; Mai e Ty Lee, à Nação do Fogo.</p><a class="text-link" href="personagens.html?grupo=nao">Conheça também os não dobradores ↗</a>`}
function explorationLinks(){return `<div class="atlas-portals"><a href="personagens.html"><span>01 / PESSOAS</span><h3>Quem faz<br>a história.</h3><p>Dobradores, inventores e guerreiros.</p><b>Explorar personagens ↗</b></a><a href="dobras.html"><span>02 / HABILIDADES</span><h3>Além dos<br>quatro elementos.</h3><p>Metal, lava, sangue e muito mais.</p><b>Conhecer as dobras ↗</b></a><a href="criaturas.html"><span>03 / VIDA E ESPÍRITOS</span><h3>Um mundo<br>extraordinário.</h3><p>Companheiros, mestres e guardiões.</p><b>Encontrar criaturas ↗</b></a></div>`}
function directoryIntro(kicker,title,text,key){return `<section class="page-intro directory-intro" style="--directory-image:url('assets/environment-${key}.svg')"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${text}</p><div class="directory-shortcuts"><a href="personagens.html">Personagens ↗</a><a href="dobras.html">Dobras ↗</a><a href="criaturas.html">Criaturas ↗</a></div></section>`}
function charactersPage(){return `${directoryIntro('O ATLAS / PERSONAGENS','Dons diferentes.<br><em>Histórias que se cruzam.</em>','Encontre personagens das eras de Aang, Korra e Seven Havens por sua dobra, habilidades e participação na história.','earth')}<section class="section directory-section"><div class="directory-toolbar"><label class="directory-search" for="cast-search">Encontre um personagem<input id="cast-search" type="search" placeholder="Nome ou habilidade: Asami, metal…" autocomplete="off"></label><label class="directory-era" for="cast-era">Era<select id="cast-era"><option value="all">Todas as eras</option>${Object.entries(ERAS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><div class="catalog-filters" role="group" aria-label="Filtrar personagens por habilidade"><button class="active" data-cast-filter="all" aria-pressed="true">Todos</button>${Object.entries(GROUPS).map(([k,v])=>`<button data-cast-filter="${k}" aria-pressed="false">${k==='nao'?'':icon(k)}${v}</button>`).join('')}</div><p id="cast-count" class="catalog-count" aria-live="polite">${CAST.length} personagens</p><div class="cast-grid">${CAST.map(characterCard).join('')}</div><p class="catalog-empty" hidden>Nenhum personagem encontrado. Experimente outro nome ou remova os filtros.</p><p class="editor-note">Seleção de personagens das animações, com spoilers de habilidades e afiliações. Os retratos complementares foram encontrados na Avatar Wiki; a origem de cada imagem está nos detalhes da ficha. A página de Avatares reúne outras encarnações do ciclo.</p></section>${landscape('water','Nem todo herói<br><em>precisa dobrar.</em>','ESTRATÉGIA / CORAGEM / ENGENHO','Sokka, Suki, Ty Lee e Asami mostram como treino, ideias e tecnologia também mudam o rumo do mundo.','personagens.html?grupo=nao','Ver não dobradores')}${sources(['studios','characters','korra1','korra3','korra4','havensPress'])}`}
function bendingPage(){return `${directoryIntro('O ATLAS / GUIA DE DOBRAS','Quatro elementos.<br><em>Muitas possibilidades.</em>','Um guia das bases, especializações e técnicas espirituais vistas nas animações. Abra as fichas para descobrir limites, usuários e episódios.','fire')}<section class="section bending-intro"><div><span class="eyebrow">ANTES DE COMEÇAR</span><h2>A técnica muda.<br>O elemento continua.</h2></div><p>Metal e lava pertencem à terra. Relâmpagos e combustão se ligam ao fogo. Bloqueio de chi é uma habilidade de combate usada por não dobradores. Nem todo praticante de um elemento domina suas especializações.</p></section><section class="section directory-section"><div class="catalog-filters" role="group" aria-label="Filtrar técnicas"><button class="active" data-tech-filter="all" aria-pressed="true">Todas</button>${Object.entries(ELEMENTS).map(([k,e])=>`<button data-tech-filter="${k}" aria-pressed="false">${icon(k)} ${e.name}</button>`).join('')}<button data-tech-filter="especial" aria-pressed="false">Energia</button></div><p class="catalog-count" id="tech-count" aria-live="polite">${BENDING.length} técnicas e aplicações</p><div class="bending-grid">${BENDING.map((t,i)=>`<article class="bending-card ${t.element}" data-tech-element="${t.element}" id="${t.id}"><div class="bending-card-head"><span>${String(i+1).padStart(2,'0')}</span>${icon(t.element)}</div><span class="eyebrow">${t.element==='especial'?'Energia':ELEMENTS[t.element].name} / ${t.type}</span><h2>${t.name}</h2><p>${t.text}</p><details><summary>Quem usa e onde aparece</summary><dl><dt>Usuários conhecidos</dt><dd>${t.users}</dd><dt>Na animação</dt><dd>${t.episode}</dd></dl>${link(t.source)}</details></article>`).join('')}</div></section>${landscape('air','Dominar também é<br><em>aprender a escutar.</em>','CORPO / MOVIMENTO / ESPÍRITO','A dobra combina prática, percepção e a relação de cada pessoa com o mundo. Seus limites fazem parte das histórias.','criaturas.html#mestres','Conheça os mestres originais')}<section class="section bending-notes"><h2>Algumas distinções importantes.</h2><div><article><h3>Bloqueio de chi</h3><p>Ty Lee atinge pontos de pressão para impedir movimentos e a dobra temporariamente. Ela não controla um elemento.</p>${link('studios')}</article><article><h3>Estado Avatar</h3><p>É uma condição ligada ao poder espiritual do Avatar. Não é um quinto elemento nem uma técnica disponível a qualquer dobrador.</p>${link('wan')}</article><article><h3>Origem e aprendizado</h3><p>As tartarugas-leão concedem o poder dos elementos na história de Wan. A Lua e os animais mestres inspiram formas de praticar a dobra.</p>${link('wan')}</article></div></section>${sources(['rare','lessons','jinora','bolin','katara','zuko'])}`}
function creatureCard(c){return `<article class="creature-card" id="${c.id}">${c.pairedImages?`<div class="creature-image creature-pair">${c.pairedImages.map(([file,name])=>pic(file,name)).join('')}</div>`:c.image?`<div class="creature-image">${pic(c.image,c.name)}</div>`:`<div class="creature-symbol" aria-hidden="true">${icon(c.group==='mestres'?'compass':c.group==='espiritos'?'star':'ar')}</div>`}<div><span class="eyebrow">${c.species}</span><h3>${c.name}</h3><p>${c.text}</p><details><summary>Na história e fonte</summary><p>${c.episode}</p>${link(c.source)}${portraitSource(c)}</details></div></article>`}
function creaturesPage(){const groups=[['companheiros','01 / AO LADO DA EQUIPE','Amizades de outro tamanho.'],['mestres','02 / OBSERVAR PARA APRENDER','Os primeiros mestres.'],['espiritos','03 / ENTRE DOIS MUNDOS','A natureza também tem voz.']];return `${directoryIntro('O ATLAS / CRIATURAS E ESPÍRITOS','O mundo vive.<br><em>E surpreende.</em>','Bisões voadores, dragões, animais híbridos e espíritos: conheça alguns dos seres que dão vida às jornadas de Avatar.','air')}<nav class="creature-jumps" aria-label="Grupos de criaturas"><a href="#companheiros">Companheiros ↓</a><a href="#mestres">Mestres originais ↓</a><a href="#espiritos">Espíritos ↓</a></nav>${groups.map(([key,kicker,title],i)=>`<section class="section creature-section" id="${key}">${sectionHead(kicker,title)}${key==='mestres'?'<p class="creature-section-note">A água tem na Lua sua inspiração original. Terra, fogo e ar se conectam às toupeiras-texugo, aos dragões e aos bisões voadores. As tartarugas-leão ocupam outro papel: concedem o poder dos elementos.</p>':''}<div class="creature-grid">${CREATURES.filter(c=>c.group===key).map(creatureCard).join('')}</div></section>${i===0?landscape('earth','Paisagens que guardam<br><em>muitas vidas.</em>','CADA CAMINHO, UMA DESCOBERTA','Das montanhas aos polos, o ambiente não é apenas um pano de fundo: ele molda a cultura, a dobra e os encontros de cada jornada.'):''}`).join('')}${sources(['appa','studios','aang1','aang2','aang3','korra1','wan','havensPress'])}`}
function initAtlasDirectories(){
 const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 if(page==='personagens'){
  const params=new URLSearchParams(location.search);let filter=GROUPS[params.get('grupo')]?params.get('grupo'):'all';
  const field=document.querySelector('#cast-search'),era=document.querySelector('#cast-era'),buttons=[...document.querySelectorAll('[data-cast-filter]')];
  const update=()=>{let n=0;for(const card of document.querySelectorAll('[data-cast-element]')){const visible=(filter==='all'||card.dataset.castElement===filter)&&(era.value==='all'||card.dataset.era===era.value)&&norm(card.dataset.search).includes(norm(field.value.trim()));card.hidden=!visible;if(visible)n++;}buttons.forEach(b=>{const active=b.dataset.castFilter===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelector('#cast-count').textContent=`${n} ${n===1?'personagem encontrado':'personagens encontrados'}`;document.querySelector('.catalog-empty').hidden=n!==0;};
  buttons.forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.castFilter;update()}));field.addEventListener('input',update);era.addEventListener('change',update);update();
 }
 if(page==='dobras')document.querySelectorAll('[data-tech-filter]').forEach(b=>b.addEventListener('click',()=>{let n=0;document.querySelectorAll('[data-tech-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('[data-tech-element]').forEach(c=>{c.hidden=b.dataset.techFilter!=='all'&&c.dataset.techElement!==b.dataset.techFilter;if(!c.hidden)n++});document.querySelector('#tech-count').textContent=`${n} técnicas e aplicações`;}));
}
